import assert from "node:assert/strict";
console.log(JSON.stringify({node:process.version,icu:process.versions.icu,platform:process.platform,arch:process.arch}));
for (const entry of ["@poe-platform/safe-js","@poe-platform/safe-js/core","@poe-platform/safe-js/workerd"]) {
const {run}=await import(entry);
assert.deepEqual((await run('return [typeof process,typeof require,typeof fetch,typeof fs,typeof document,typeof Promise];')).returnValue,["undefined","undefined","undefined","undefined","undefined","function"]);
assert.equal((await run('return process;')).ok,false);
await assert.rejects(run('import * as authority from "node:fs"; return authority;'),/Invalid import specifier/);
await assert.rejects(run('import * as authority from "acorn"; return authority;'),/Unknown module/);
assert.deepEqual((await run('import {read} from "store"; return [read(),typeof fs,typeof fetch];',{modules:{store:{read:()=>"grant"}}})).returnValue,["grant","undefined","undefined"]);
console.log(entry,"PASS");
}

